"use client";

/**
 * Ctrl+K search overlay; advanced syntax requires `advanced_search`.
 *
 * Must call (do not reimplement): isEnabled
 */
import { useEffect, useState } from "react";
import { Dialog } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Spinner } from "@/components/ui/spinner";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useDebouncedValue } from "@/hooks/use-debounced-value";
import { isEnabled } from "@/lib/feature-flags";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchHit } from "@/server/services/search-service";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { ReactElement } from "react";
import { describeQuery, parseSearchQuery } from "./query-syntax";
import { SearchResults } from "./search-results";

export type SearchDialogProps = {
  open: boolean;
  orgId: OrgId;
  flags: FeatureFlagSnapshot;
  onClose: () => void;
  onSearch: (input: SearchQueryInput) => Promise<ActionResult<SearchHit[]>>;
};

const SEARCH_PAGE_SIZE = 20;

export function SearchDialog(props: SearchDialogProps): ReactElement | null {
  const { open, orgId, flags, onClose, onSearch } = props;

  const [raw, setRaw] = useState("");
  // Results are stored together with the query that produced them, so
  // "still searching" is derived rather than a second piece of state that
  // could disagree with the first.
  const [results, setResults] = useState<{
    query: string;
    hits: readonly SearchHit[];
  }>({ query: "", hits: [] });

  const debounced = useDebouncedValue(raw);
  const advanced =
    flags.advanced_search === true ||
    isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });
  const parsed = parseSearchQuery(debounced, advanced);

  const query = parsed.text;
  const pending = query.length > 0 && results.query !== query;

  useEffect(() => {
    if (!open || query.length === 0) return;

    let cancelled = false;

    void onSearch({
      orgId,
      q: query,
      kinds: [...parsed.kinds],
      ...(parsed.projectId !== null ? { projectId: parsed.projectId } : {}),
      limit: SEARCH_PAGE_SIZE,
    }).then((result) => {
      if (cancelled) return;
      setResults({ query, hits: result.ok ? result.data : [] });
    });

    return () => {
      cancelled = true;
    };
    // `parsed` is derived from the debounced string; depending on its parts
    // keeps the effect from re-firing on every keystroke.
  }, [open, orgId, onSearch, query, parsed.kinds, parsed.projectId]);

  if (!open) return null;

  return (
    <Dialog
      open={open}
      title="Search"
      description={
        advanced
          ? "Use kind:issue or project:<id> to narrow the search."
          : undefined
      }
      onClose={onClose}
    >
      <Input
        name="q"
        type="search"
        value={raw}
        placeholder={advanced ? "kind:comment deploy failed" : "Search…"}
        onChange={setRaw}
      />

      {advanced && debounced.length > 0 ? (
        <p className="mt-1 text-xs text-neutral-500">{describeQuery(parsed)}</p>
      ) : null}

      <div className="mt-3">
        {pending ? (
          <Spinner size="sm" label="Searching" />
        ) : (
          <SearchResults
            hits={results.query === query ? results.hits : []}
            query={query}
            onSelect={() => onClose()}
          />
        )}
      </div>
    </Dialog>
  );
}
/**
 * The `advanced_search` query language.
 *
 * A plain query is just terms. With the flag on, `kind:` and `project:`
 * prefixes narrow the search before it reaches the index, which is why the
 * parser lives on the client too: the dialog has to show the user what it
 * understood before it spends a round trip.
 */
import type { ProjectId } from "@/types/common";

export type SearchSubjectKind = "issue" | "comment" | "project";

const KINDS: readonly SearchSubjectKind[] = ["issue", "comment", "project"];

export interface ParsedSearchQuery {
  /** The free-text remainder, with every recognised token removed. */
  readonly text: string;
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  /** Tokens that looked like syntax but named nothing we know. */
  readonly unknownTokens: readonly string[];
}

export const DEFAULT_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];

/**
 * @param raw      what the user typed
 * @param advanced whether the `advanced_search` flag is on for this org; when
 *                 false the whole string is treated as free text so a colon in
 *                 a title still finds the title.
 */
export function parseSearchQuery(
  raw: string,
  advanced: boolean,
): ParsedSearchQuery {
  if (!advanced) {
    return {
      text: raw.trim(),
      kinds: DEFAULT_SEARCH_KINDS,
      projectId: null,
      unknownTokens: [],
    };
  }

  const terms: string[] = [];
  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: ProjectId | null = null;

  for (const token of raw.split(/\s+/).filter((part) => part.length > 0)) {
    const separator = token.indexOf(":");
    if (separator <= 0) {
      terms.push(token);
      continue;
    }

    const field = token.slice(0, separator).toLowerCase();
    const value = token.slice(separator + 1);
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
      if (KINDS.includes(kind)) kinds.push(kind);
      else unknown.push(token);
    } else if (field === "project") {
      projectId = value as ProjectId;
    } else {
      unknown.push(token);
    }
  }

  return {
    text: terms.join(" "),
    kinds: kinds.length > 0 ? kinds : DEFAULT_SEARCH_KINDS,
    projectId,
    unknownTokens: unknown,
  };
}

/** A one-line explanation of what the parser understood, for the dialog. */
export function describeQuery(parsed: ParsedSearchQuery): string {
  const parts = [`searching ${parsed.kinds.join(", ")}`];
  if (parsed.projectId !== null) parts.push(`in project ${parsed.projectId}`);
  if (parsed.unknownTokens.length > 0) {
    parts.push(`ignoring ${parsed.unknownTokens.join(", ")}`);
  }
  return parts.join(" · ");
}
/**
 * JSON search endpoint used by the command palette.
 *
 * Owner D. The palette hits this route rather than the Server Action because it
 * fires on every keystroke and wants a plain cancellable fetch; the gating is
 * identical to `searchAction`, deliberately duplicated so neither entry point
 * can be the lenient one.
 *
 * Must call (do not reimplement): can, isEnabled
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { searchQuerySchema } from "@/schemas/search";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { search } from "@/server/services/search-service";

export const dynamic = "force-dynamic";

const PALETTE_LIMIT = 10;

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    const q = url.searchParams.get("q");

    if (orgSlug === null || q === null) {
      return failure("validation_failed", "orgSlug and q are required.");
    }

    const actor = await getActor(orgSlug);

    if (!can(actor, "org:read", { kind: "organization", orgId: actor.orgId })) {
      return failure("forbidden", "You cannot search this organization.");
    }

    const { organization } = await getOrganizationSummary(actor, actor.orgId);
    const context = buildFlagContext(actor, organization);

    if (!isEnabled("command_palette", context)) {
      return failure("forbidden", "The command palette is not enabled here.");
    }

    const parsed = searchQuerySchema.safeParse({
      orgId: actor.orgId,
      q,
      kinds: isEnabled("advanced_search", context)
        ? ["issue", "comment", "project"]
        : ["issue"],
      limit: PALETTE_LIMIT,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad search query.");
    }

    const page = await search(actor, parsed.data);
    return Response.json({ items: page.items, total: page.total });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Full-page search results.
 *
 * Owner D. The command palette and this page share one action, so the flag
 * check has to live in both places — the palette narrows what it asks for, and
 * this page explains why comments are missing from the results.
 *
 * Must call (do not reimplement): isEnabled
 */

import Link from "next/link";
import type { Metadata } from "next";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { searchQuerySchema } from "@/schemas/search";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { search as runSearch } from "@/server/services/search-service";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Search",
};

const RESULT_LIMIT = 30;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const advanced = isEnabled("advanced_search", buildFlagContext(actor, org));
  const query = typeof search.q === "string" ? search.q : "";

  if (query.length === 0) {
    return (
      <div className="space-y-8">
        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
        <EmptyState
          title="Search this organization"
          description="Type at least one character to look through issues, and — on the higher plans — comments and projects too."
        />
      </div>
    );
  }

  const parsed = searchQuerySchema.safeParse({
    orgId: org.id,
    q: query,
    kinds: advanced ? ["issue", "comment", "project"] : ["issue"],
    limit: RESULT_LIMIT,
  });

  if (!parsed.success) {
    return (
      <div className="space-y-8">
        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
        <EmptyState title="That query is not valid" description="Try something shorter." />
      </div>
    );
  }

  const page = await runSearch(actor, parsed.data);

  return (
    <div className="space-y-8">
      <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />

      {page.items.length === 0 ? (
        <EmptyState title={`Nothing matches “${query}”`} />
      ) : (
        <ul className="space-y-4">
          {page.items.map((hit) => (
            <li key={`${hit.kind}:${hit.id}`}>
              <Link href={hit.href} className="block">
                <span className="text-xs uppercase tracking-wide text-slate-400">
                  {hit.kind}
                </span>
                <span className="mt-0.5 block text-sm font-medium">
                  {hit.title}
                </span>
                <span className="mt-0.5 block text-sm text-slate-600">
                  {hit.snippet}
                </span>
              </Link>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function SearchHeader(props: {
  orgSlug: string;
  query: string;
  advanced: boolean;
}) {
  return (
    <header>
      <h1 className="text-2xl font-semibold tracking-tight">Search</h1>
      <form action={`/${props.orgSlug}/search`} className="mt-4 max-w-md">
        <input
          name="q"
          type="search"
          defaultValue={props.query}
          placeholder="Search issues…"
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </form>
      {!props.advanced ? (
        <p className="mt-2 text-xs text-slate-500">
          Comments and projects are searchable on the growth plan and above.
        </p>
      ) : null}
    </header>
  );
}
/**
 * Token-bucket limiter applied to invites, comments, search and password
 * resets.
 *
 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
 * runs single-writer, and the corpus has no external cache. Capacity scales
 * with the org's plan through `getPlanLimits()`, so a growth org is not held
 * to a free org's ceiling; the per-bucket shape below is the base rate.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

export type RateLimitVerdict = {
  allowed: boolean;
  remaining: number;
  resetAt: IsoTimestamp;
};

export type RateLimitConfig = { capacity: number; refillPerMinute: number };

export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
  "member:invite": { capacity: 20, refillPerMinute: 2 },
  "comment:create": { capacity: 60, refillPerMinute: 20 },
  "issue:create": { capacity: 60, refillPerMinute: 20 },
  "search:query": { capacity: 120, refillPerMinute: 60 },
  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
};

/** Applied to any key not in the table above. */
const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };

type BucketState = { tokens: number; updatedAt: number };

const buckets = new Map<string, BucketState>();

/** Plan-aware org context; services set this when they know the org's plan. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

/**
 * Scales the base bucket by the org's hourly API allowance, so the limiter
 * and the plan catalogue can never drift apart: the plan is the source of
 * the ceiling, this table only sets the relative shape.
 */
function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const plan = planByOrg.get(orgId) ?? "free";
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

/**
 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 * Async because the production limiter is expected to move behind a store —
 * every call site already awaits it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    state.tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs });

  const deficit = allowed ? config.capacity - remaining : cost - remaining;
  const minutesToReset =
    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;

  return {
    allowed,
    remaining: Math.floor(remaining),
    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
  };
}

/** Test-only: drops every bucket and org plan association. */
export function resetRateLimits(): void {
  buckets.clear();
  planByOrg.clear();
}
import {
  FEATURE_FLAG_DEFINITIONS,
  FEATURE_FLAG_KEYS,
} from "@/config/feature-flags";
import { planAtLeast } from "@/config/plan-limits";
import { ROLE_RANK } from "@/types/member";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";

/**
 * Feature-flag evaluation, shared verbatim by server and client.
 *
 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
 * directly; the dashboard layout serialises `snapshotFlags()` into the client
 * provider so `useFeatureFlag()` answers the same way without a round trip.
 * Both sides must agree — never re-implement a strategy at a call site.
 */
export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
  const definition = FEATURE_FLAG_DEFINITIONS[flag];
  if (!definition) return false;

  if (definition.overridable && ctx.overrides?.includes(flag)) {
    return true;
  }

  const strategy = definition.strategy;
  switch (strategy.kind) {
    case "off":
      return false;
    case "on":
      return true;
    case "plan":
      return planAtLeast(ctx.plan, strategy.minPlan);
    case "role":
      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    case "percentage":
      return bucketOf(flag, ctx) < strategy.percent;
    default:
      return false;
  }
}

/** Evaluates every flag at once, for handoff to the client provider. */
export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
  const snapshot = {} as Record<FeatureFlagKey, boolean>;
  for (const key of FEATURE_FLAG_KEYS) {
    snapshot[key] = isEnabled(key, ctx);
  }
  return snapshot;
}

/** Throwing guard for server actions gated behind a flag. */
export class FeatureDisabledError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: FeatureFlagKey) {
    super(`Feature "${flag}" is not enabled for this organization.`);
    this.name = "FeatureDisabledError";
  }
}

export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
  if (!isEnabled(flag, ctx)) {
    throw new FeatureDisabledError(flag);
  }
}

/**
 * Deterministic 0–99 bucket for percentage rollouts. Stable per
 * (flag, org, user) so a viewer never sees the feature flicker.
 */
function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
  let hash = 2_166_136_261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash) % 100;
}
import type { OrgId, TenantScoped } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Multi-tenancy invariant helpers.
 *
 * Every repository query must be filtered by `org_id`, and every row that
 * crosses a service boundary must be re-checked against the actor's org. These
 * helpers are the only sanctioned way to express that — a hand-written
 * `if (row.orgId !== actor.orgId)` is a review failure.
 */

export class TenantScopeError extends Error {
  readonly code = "tenant_scope_violation" as const;

  constructor(
    readonly expectedOrgId: OrgId,
    readonly actualOrgId: OrgId,
  ) {
    super(
      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    );
    this.name = "TenantScopeError";
  }
}

/** Throws unless `orgId` belongs to the actor's organization. */
export function assertOrgScope(actor: Actor, orgId: OrgId): void {
  if (actor.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, orgId);
  }
}

/** Throws unless every supplied row belongs to the actor's organization. */
export function assertRowsInScope<T extends TenantScoped>(
  actor: Actor,
  rows: readonly T[],
): void {
  for (const row of rows) {
    assertOrgScope(actor, row.orgId);
  }
}

/** Non-throwing predicate, for filtering rather than failing. */
export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
  return row.orgId === actor.orgId;
}

/** Narrows a nullable row to one the actor may see; `null` otherwise. */
export function scopedOrNull<T extends TenantScoped>(
  actor: Actor,
  row: T | null | undefined,
): T | null {
